  ('5bf591c3-3ee8-5b3a-a7b6-4b774ad64dc0', 1, 21, 21, 'treinta-y-cuatro', 'Count to a hundred and say your real age', 'Tengo treinta y cuatro años', array['numeros.21-100', 'tener.pres.1sg-3sg']::text[], 'informal', '{}'::uuid[], 'published'),
  ('3bfdac76-f836-5268-91f3-0dbfa1c26018', 1, 26, 26, 'cuanto-cuesta', 'Ask what it costs', '¿Cuánto sale?', array['cuanto-sale', 'costar.pres.3', 'numeros.miles']::text[], 'informal', '{}'::uuid[], 'published'),
  ('bde97495-163d-56bd-a579-b524910edfcc', 2, 7, 34, 'adonde-vas', 'Say where you''re going', '¿Adónde vas? Voy a la plaza', array['ir.pres', 'ir-a.lugar', 'contraccion.del-al']::text[], 'informal', '{}'::uuid[], 'published'),
  ('525526ce-1e8d-5672-88f4-02259c8e4533', 2, 13, 40, 'hoy-y-manana', 'Say when: today, tomorrow, now', 'Hoy laburo, mañana no', array['tiempo.hoy-manana-ahora', 'a-la-noche']::text[], 'informal', '{}'::uuid[], 'published'),
  ('26b3f81c-f349-5b38-817b-731bbac652cf', 3, 12, 66, 'este-y-ese', 'Point at things: this one, that one', 'Esa mochila es re linda', array['demostrativos.este-ese', 'demostrativos.neutro', 're.intensificador']::text[], 'informal', '{}'::uuid[], 'published'),
  ('70cf9841-8e17-590c-9fd0-503d47b7b3e1', 3, 13, 67, 'la-campera-nueva', 'Talk about your clothes', 'Esta campera es nueva', array['adj.concordancia', 'ser.descripcion']::text[], 'informal', '{}'::uuid[], 'published'),
  ('694523fc-5d19-5d81-8e08-6083c35d7d25', 4, 2, 82, 'estoy-llegando', 'Say what you''re doing right now', 'Ya estoy llegando', array['estar.gerundio', 'ya-todavia']::text[], 'informal', '{}'::uuid[], 'published'),
  ('59190ff0-c3f5-5d61-bd69-5db02edca9fd', 4, 4, 84, 'que-decis', 'Say, see and put: three everyday verbs', '¿Qué decís? No veo nada', array['decir.pres', 'ver.pres', 'poner.pres']::text[], 'informal', '{}'::uuid[], 'published')
