insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('3ddb4cb9-dbfd-5829-b717-aec8064fbb90', '9f62a065-778e-5620-b8e5-de9e6f8c2907', 'Hablo, hablás', 'The *I* form ends in **-o**: **hablo**, **entiendo**. The vos form is stressed on the end: **hablás**, **entendés**, **repetís**. One verb is different: *I know* is just **sé**, and the vos form is **sabés**. *No entiendo. ¿Hablás inglés?* — *No sé.*', 'published'),
  ('1f4b9651-418e-5f8c-a3bf-03626d36a760', '9f62a065-778e-5620-b8e5-de9e6f8c2907', 'Ask for help', 'Stuck on a word: **¿cómo se dice…?** — *how do you say…?* — and **¿qué significa?** — *what does it mean?* Too fast: **más despacio, por favor**. And the line that buys you patience: **hablo un poco** — *I speak a little*. Argentines call the language **castellano**.', 'published'),
  ('0a165b34-8a68-50c2-973b-ae40dc128454', '5bf591c3-3ee8-5b3a-a7b6-4b774ad64dc0', 'Veinticinco, treinta y cuatro', 'From 21 to 29 the number is one word: **veintiuno**, **veintidós**, **veinticinco**. From **treinta** on it is three words joined by **y**: *Tengo treinta y cuatro años.* The same pattern works for **cuarenta**, **cincuenta** and all the way up to **noventa**.', 'published'),
  ('ae4f4e8b-34af-508d-8cc2-5d3e4564bb87', '5bf591c3-3ee8-5b3a-a7b6-4b774ad64dc0', 'Sesenta or setenta?', '**Sesenta** (60) and **setenta** (70) are the pair everyone mixes up: **sesenta** has the **s** of *six*, **setenta** has the **t** of *seven*. And a round hundred is just **cien** — never *un cien*.', 'published'),
  ('2b07464d-38f9-507b-bfa2-be0acb5aa850', '3bfdac76-f836-5268-91f3-0dbfa1c26018', '¿Cuánto sale?', '**¿Cuánto sale?** is the everyday Argentine way to ask a price — **¿cuánto cuesta?** works too and means the same. For more than one thing the verb changes: **¿cuánto salen?**, **¿cuánto cuestan?**', 'published'),
  ('b29680d4-b383-5aa7-a81f-ac7b3e1b8450', '3bfdac76-f836-5268-91f3-0dbfa1c26018', 'Mil, never un mil', 'Argentine prices run into the thousands, so you will say **mil** all day. One thousand is just **mil** — never *un mil* — and the word does not change: *Sale mil pesos.* *¿Mil pesos? Es caro.*', 'published'),
  ('6e364ee3-389f-55b3-a895-bd88f35dc318', 'bde97495-163d-56bd-a579-b524910edfcc', 'Voy, vas, va', '**Ir** — *to go* — looks nothing like its forms: **voy**, **vas**, **va**, **vamos**, **van**. Spanish uses one form for *I go* and *I''m going*: *Voy a la plaza* is both. And **vamos** on its own also means *let''s go*.', 'published'),
  ('29afb672-4c8b-59dd-85ee-eef456a2127a', 'bde97495-163d-56bd-a579-b524910edfcc', 'Always with a', 'Going somewhere takes **a** — *to* — every time: *Voy a la plaza.* The question word has that **a** built in: **¿adónde vas?** is *where are you going to?* English often drops the *to*; Spanish never drops the **a**.', 'published'),
  ('11dfb570-d80f-5e13-a3ef-5cfff6079ac5', '525526ce-1e8d-5672-88f4-02259c8e4533', 'Two mañanas', '**Mañana** on its own is *tomorrow*: *Hoy laburo, mañana no.* With **la** it is *the morning*, and porteños say **a la mañana** for *in the morning*. So *tomorrow morning* is **mañana a la mañana**.', 'published'),
  ('5d601854-1cc7-5d99-961d-5454185bfc90', '525526ce-1e8d-5672-88f4-02259c8e4533', 'Tarde: afternoon or late', '**Tarde** works the same way. **A la tarde** is *in the afternoon*; on its own **tarde** means *late*: *Es tarde.* Its opposite is **temprano** — *early*: *Es temprano.*', 'published'),
  ('ccecffed-c0a3-59ba-b6b7-db2c4a7c140d', '26b3f81c-f349-5b38-817b-731bbac652cf', 'Este here, ese there', '**Este** is *this*, near you; **ese** is *that*, further away. Both match the noun: **este** café, **esa** mochila, and **estos**, **estas**, **esos**, **esas** for more than one. *Esa mochila es re linda* — **re** before an adjective is the porteño *really*.', 'published'),
  ('c2b30f52-c7e5-5023-9df0-92d83a8d3c18', '26b3f81c-f349-5b38-817b-731bbac652cf', 'Esto and eso', 'When you don''t know the word — or don''t need it — use **esto** (this thing here) and **eso** (that thing there). They never change and no noun comes after them: *Quiero eso, por favor.*', 'published'),
  ('3780b464-8070-51f5-84a8-d6507d0dfa2e', '70cf9841-8e17-590c-9fd0-503d47b7b3e1', 'Un pantalón, un jean', 'One pair of pants is **un pantalón** — singular: *Mi pantalón es nuevo.* *Los pantalones* works too. The same goes for **un jean**. And **ropa** — *clothes* — is always singular: *Mi ropa es nueva.*', 'published'),
  ('5f0726c3-0c2e-524a-b89f-9832deab7142', '70cf9841-8e17-590c-9fd0-503d47b7b3e1', 'Nuevo, nueva', 'The adjective copies its noun: *una campera nueva*, *un jean nuevo*, *los pantalones chicos*. **Grande** has one form for both: *una remera grande*, *las zapatillas grandes*. And it comes after the noun, not before as in English.', 'published'),
  ('f81f6472-4ab5-5b1d-97bd-3ad25b1a3ad1', '694523fc-5d19-5d81-8e08-6083c35d7d25', '-ando, -iendo', 'Verbs in *-ar* take **-ando**: **laburando**, **esperando**, **tomando**. Verbs in *-er* and *-ir* take **-iendo**: **comiendo**, **haciendo**. That ending never changes — only *estar* does: *Estoy comiendo.* *Está tomando un café.*', 'published'),
  ('ffce8d24-cbec-5893-93f5-546baf4d2390', '694523fc-5d19-5d81-8e08-6083c35d7d25', 'Ya, todavía, casi', '**Ya** is *already* or *right now*; **todavía** is *still*: *Todavía estoy laburando.* *Todavía no* is *not yet*. **Casi** is *almost*. One warning: in Buenos Aires **ya estoy llegando** can mean you are still ten minutes away.', 'published'),
  ('ba82ffe4-0152-5484-bf4b-85a5828f972a', '59190ff0-c3f5-5d61-bd69-5db02edca9fd', 'Digo, pongo, veo', 'Like *vengo* and *traigo*, these verbs have an odd *I* form: **digo**, **pongo** and **veo**. With vos they are regular: **decís**, **ponés**, **ves**. *Decir* also changes **e** to **i** in **dice** and **dicen**. *¿Qué decís? — Yo no digo nada.*', 'published'),
  ('a2908aec-4964-564b-be6f-345aab4ac907', '59190ff0-c3f5-5d61-bd69-5db02edca9fd', 'No veo nada', 'English says *I can''t see anything*; Spanish just says **no veo nada** — no word for *can*. The same with **ves**: *¿Ves?* is *can you see?* And the double negative is correct Spanish: *no* before the verb, *nada* after it.', 'published')
